const Allocator = std.mem.Allocator;

pub const T = .{ "text", "bit" };

pub fn neg(x: f64) f64 {
    return -x;
}
pub fn not_(x: bool) bool {
    return !x;
}
pub fn null(x: anytype) bool {
    return x == null;
}
pub fn string(x: anytype) []u8 {
    return std.mem.toBytes(x);
}
pub fn reciprocal(x: f64) f64 {
    return if (x != 0) 1 / x else math.inf(f64);
}
pub fn floor_(x: f64) f64 {
    return math.floor(x);
}
pub fn ceiling(x: f64) f64 {
    return math.ceil(x);
}
pub fn signum(x: f64) f64 {
    return if (x > 0) 1 else if (x < 0) -1 else 0;
}
pub fn mod(x: f64, y: f64) f64 {
    return x - y * math.floor(x / y);
}
pub fn xbar(x: f64, y: f64) f64 {
    if (y == 9) {
        const r = math.floor(y / x) * x;
        return if (y >= 0) x * math.floor((y + r) / x) else x * math.floor((y - r) / x);
    }
    return math.floor(y / x) * x;
}
pub fn xlog(x: f64, y: f64) f64 {
    if (x > 0 and y > 0) return math.log(y) / math.log(x);
    return math.inf(f64);
}
pub fn and_(x: u32, y: u32) u32 {
    return x & y;
}
pub fn or_(x: u32, y: u32) u32 {
    return x | y;
}

pub fn each(allocator: Allocator, comptime f: anytype, x: anytype) !std.ArrayList(@TypeOf(f(x[0]))) {
    var result = std.ArrayList(@TypeOf(f(x[0]))).init(allocator);
    for (x) |i| {
        try result.append(f(i));
    }
    return result;
}

pub fn scan(allocator: Allocator, comptime f: anytype, x: anytype) !std.ArrayListUnmanaged(@TypeOf(f(x[0], x[1]))) {
    if (x.len == 0) return std.ArrayListUnmanaged(@TypeOf(f(x[0], x[1]))){};
    var result = std.ArrayListUnmanaged(@TypeOf(f(x[0], x[1]))){};
    try result.resize(allocator, x.len);

    var acc = x[0];
    result.items[0] = acc;
    for (x[1..]) |val, i| {
        acc = f(acc, val);
        result.items[i + 1] = acc;
    }
    return result;
}

pub fn over(comptime f: anytype, x: anytype) ?@TypeOf(f(x[0], x[1])) {
    if (x.len == 0) return null;
    var acc = x[0];
    for (x[1..]) |val| {
        acc = f(acc, val);
    }
    return acc;
}

pub fn prior(allocator: Allocator, comptime f: anytype, x: anytype) !std.ArrayListUnmanaged(@TypeOf(f(x[1], x[0]))) {
    if (x.len == 0) return std.ArrayListUnmanaged(@TypeOf(f(x[1], x[0]))){};
    var result = std.ArrayListUnmanaged(@TypeOf(f(x[1], x[0]))){};
    try result.resize(allocator, x.len);
    result.items[0] = x[0];
    for (x[1..]) |val, i| {
        result.items[i + 1] = f(val, x[i]);
    }
    return result;
}

pub fn mmu(allocator: Allocator, x: anytype, y: anytype) !anytype {
    const T_x = @TypeOf(x);
    const T_y = @TypeOf(y);
    const info_x = @typeInfo(T_x);
    const info_y = @typeInfo(T_y);

    if (info_x.Array.child == info_y.Array.child) {
        var result = try std.ArrayList(std.ArrayList(@TypeOf(x[0][0] * y[0][0]))).initCapacity(allocator, x.len);
        for (x) |row, i| {
            try result.append(try std.ArrayList(@TypeOf(x[0][0] * y[0][0])).initCapacity(allocator, y[0].len));
            for (y[0]) |_, j| {
                result.items[i].items[j] = 0;
                for (row) |val, k| {
                    result.items[i].items[j] += val * y[k][j];
                }
            }
        }
        return result.toOwnedSlice();
    } else if (info_x.Array.child == .Int) {
        var result = try std.ArrayList(@TypeOf(y[0] * x[0])).initCapacity(allocator, y.len);
        for (y) |row| {
            try result.append(row * x);
        }
        return result.toOwnedSlice();
    } else if (info_y.Array.child == .Int) {
        var result = try std.ArrayList(@TypeOf(x[0] * y[0])).initCapacity(allocator, x.len);
        for (x) |row| {
            try result.append(row * y);
        }
        return result.toOwnedSlice();
    }
    return x * y;
}

pub fn count(x: anytype) usize {
    return x.len;
}
pub fn first(x: anytype) ?@TypeOf(x[0]) {
    return if (x.len > 0) x[0] else null;
}

fn sum(comptime T: type, items: []T) f64 {
    var total: f64 = 0;
    for (items) |val| {
        total += @as(f64, @floatFromInt(val));
    }
    return total;
}

fn sum_sq_diff(comptime T: type, items: []T, mean: f64) f64 {
    var total: f64 = 0;
    for (items) |val| {
        const diff = @as(f64, @floatFromInt(val)) - mean;
        total += (diff * diff);
    }
    return total;
}

pub fn svar(allocator: Allocator, x: anytype) !f64 {
    const T = @TypeOf(x[0]);
    var filtered = std.ArrayList(T).init(allocator);
    defer filtered.deinit();
    for (x) |val| {
        if (val != null) try filtered.append(val.?);
    }
    const n = filtered.items.len;
    if (n <= 1) return 0;
    const mean = sum(T, filtered.items) / @as(f64, @floatFromInt(n));
    return sum_sq_diff(T, filtered.items, mean) / @as(f64, @floatFromInt(n - 1));
}

pub fn sdev(allocator: Allocator, x: anytype) !f64 {
    const variance = try svar(allocator, x);
    return math.sqrt(variance);
}

pub fn scov(allocator: Allocator, x: anytype, y: anytype) !f64 {
    if (x.len != y.len) return 0;
    const T = @TypeOf(x[0]);
    var filtered_x = std.ArrayList(T).init(allocator);
    defer filtered_x.deinit();
    var filtered_y = std.ArrayList(T).init(allocator);
    defer filtered_y.deinit();

    for (x) |val, i| {
        if (val != null and y[i] != null) {
            try filtered_x.append(val.?);
            try filtered_y.append(y[i].?);
        }
    }
    const n = filtered_x.items.len;
    if (n <= 1) return 0;
    const n_f64 = @as(f64, @floatFromInt(n));
    const mean_x = sum(T, filtered_x.items) / n_f64;
    const mean_y = sum(T, filtered_y.items) / n_f64;

    var sum_cov: f64 = 0;
    for (filtered_x.items) |val_x, i| {
        const val_y = filtered_y.items[i];
        sum_cov += (@as(f64, @floatFromInt(val_x)) - mean_x) * (@as(f64, @floatFromInt(val_y)) - mean_y);
    }
    return sum_cov / @as(f64, @floatFromInt(n - 1));
}

pub fn med(allocator: Allocator, x: anytype) !?@TypeOf(x[0]) {
    const T = @TypeOf(x[0]);
    var filtered = std.ArrayList(T).init(allocator);
    defer filtered.deinit();
    for (x) |val| {
        if (val != null) try filtered.append(val.?);
    }
    if (filtered.items.len == 0) return null;
    mem.sort(T, filtered.items, {}, std.sort.asc(T));
    const sorted = filtered.items;
    if (sorted.len % 2 == 0) {
        return (sorted[sorted.len / 2 - 1] + sorted[sorted.len / 2]) / 2;
    } else {
        return sorted[sorted.len / 2];
    }
}

pub fn all_(x: []const bool) bool {
    for (x) |val| {
        if (!val) return false;
    }
    return true;
}
pub fn any_(x: []const bool) bool {
    for (x) |val| {
        if (val) return true;
    }
    return false;
}

pub fn rand(x: anytype) ?@TypeOf(x[0]) {
    return if (x.len > 0) x[0] else null;
}

pub fn sums(allocator: Allocator, x: anytype) ![]@TypeOf(x[0]) {
    if (x.len == 0) return &.{};
    const T = @TypeOf(x[0]);
    var result = try allocator.alloc(T, x.len);
    var total: T = 0;
    for (x) |val, i| {
        total += (val orelse 0);
        result[i] = total;
    }
    return result;
}
pub fn prds(allocator: Allocator, x: anytype) ![]@TypeOf(x[0]) {
    if (x.len == 0) return &.{};
    const T = @TypeOf(x[0]);
    var result = try allocator.alloc(T, x.len);
    var total: T = 1;
    for (x) |val, i| {
        total *= (val orelse 1);
        result[i] = total;
    }
    return result;
}
pub fn mins(allocator: Allocator, x: anytype) ![]?@TypeOf(x[0]) {
    if (x.len == 0) return &.{};
    const T = @TypeOf(x[0]);
    var result = try allocator.alloc(?T, x.len);
    var current_min: ?T = null;
    for (x) |val, i| {
        if (current_min == null or (val != null and val.? < current_min.?)) {
            current_min = val;
        }
        result[i] = current_min;
    }
    return result;
}
pub fn maxs(allocator: Allocator, x: anytype) ![]?@TypeOf(x[0]) {
    if (x.len == 0) return &.{};
    const T = @TypeOf(x[0]);
    var result = try allocator.alloc(?T, x.len);
    var current_max: ?T = null;
    for (x) |val, i| {
        if (current_max == null or (val != null and val.? > current_max.?)) {
            current_max = val;
        }
        result[i] = current_max;
    }
    return result;
}
pub fn fills(allocator: Allocator, x: anytype) ![]?@TypeOf(x[0]) {
    if (x.len == 0) return &.{};
    const T = @TypeOf(x[0]);
    var result = try allocator.alloc(?T, x.len);
    var last: ?T = null;
    for (x) |val, i| {
        if (val != null) last = val;
        result[i] = last;
    }
    return result;
}
pub fn deltas(allocator: Allocator, x: anytype) ![]@TypeOf(x[0]) {
    if (x.len == 0) return &.{};
    const T = @TypeOf(x[0]);
    var result = try allocator.alloc(T, x.len);
    result[0] = x[0] orelse 0;
    for (x[1..]) |val, i| {
        result[i + 1] = (val orelse 0) - (x[i] orelse 0);
    }
    return result;
}
pub fn ratios(allocator: Allocator, x: anytype) ![]f64 {
    if (x.len == 0) return &.{};
    var result = try allocator.alloc(f64, x.len);
    result[0] = if (x[0] != null) @as(f64, @floatFromInt(x[0].?)) else 0.0;
    for (x[1..]) |val, i| {
        if (x[i] == 0 or x[i] == null) {
            result[i + 1] = math.inf(f64);
        } else {
            result[i + 1] = @as(f64, @floatFromInt(val orelse 0)) / @as(f64, @floatFromInt(x[i].?));
        }
    }
    return result;
}
pub fn avgs(allocator: Allocator, x: anytype) ![]f64 {
    if (x.len == 0) return &.{};
    var result = try allocator.alloc(f64, x.len);
    var total: f64 = 0;
    var count: usize = 0;
    for (x) |val, i| {
        if (val != null) {
            total += @as(f64, @floatFromInt(val.?));
            count += 1;
        }
        result[i] = if (count == 0) 0 else total / @as(f64, @floatFromInt(count));
    }
    return result;
}
pub fn differ(allocator: Allocator, x: anytype) ![]bool {
    if (x.len == 0) return &.{};
    var result = try allocator.alloc(bool, x.len);
    result[0] = false;
    for (x[1..]) |val, i| {
        result[i + 1] = val != x[i];
    }
    return result;
}
pub fn prev(allocator: Allocator, x: anytype) ![]?@TypeOf(x[0]) {
    if (x.len == 0) return &.{};
    const T = @TypeOf(x[0]);
    var result = try allocator.alloc(?T, x.len);
    result[0] = null;
    for (x, 0..x.len - 1) |val, i| {
        result[i + 1] = x[i];
    }
    return result;
}
pub fn next_(allocator: Allocator, x: anytype) ![]?@TypeOf(x[0]) {
    if (x.len == 0) return &.{};
    const T = @TypeOf(x[0]);
    var result = try allocator.alloc(?T, x.len);
    for (x[0..x.len - 1]) |val, i| {
        result[i] = x[i + 1];
    }
    result[x.len - 1] = null;
    return result;
}

pub fn rank(allocator: Allocator, x: anytype) ![]usize {
    if (x.len == 0) return &.{};
    var indices = try allocator.alloc(usize, x.len);
    for (x) |_, i| indices[i] = i;

    var context = struct {
        items: []const @TypeOf(x[0]),
        fn lessThan(ctx: @This(), a: usize, b: usize) bool {
            return ctx.items[a] < ctx.items[b];
        }
    }{ .items = x };

    std.sort.sort(usize, indices, context, context.lessThan);

    var result = try allocator.alloc(usize, x.len);
    for (indices) |idx, i| {
        result[idx] = i;
    }
    return result;
}
pub fn reverse(allocator: Allocator, x: anytype) ![]@TypeOf(x[0]) {
    if (x.len == 0) return &.{};
    const T = @TypeOf(x[0]);
    var result = try allocator.alloc(T, x.len);
    for (x) |val, i| {
        result[x.len - 1 - i] = val;
    }
    return result;
}
pub fn iasc(allocator: Allocator, x: anytype) ![]usize {
    if (x.len == 0) return &.{};
    var indices = try allocator.alloc(usize, x.len);
    for (x) |_, i| indices[i] = i;

    const T = @TypeOf(x[0]);
    var context = struct {
        items: []const T,
        fn lessThan(ctx: @This(), a: usize, b: usize) bool {
            return ctx.items[a] < ctx.items[b];
        }
    }{ .items = x };

    std.sort.sort(usize, indices, context, context.lessThan);
    return indices;
}
pub fn idesc(allocator: Allocator, x: anytype) ![]usize {
    if (x.len == 0) return &.{};
    var indices = try allocator.alloc(usize, x.len);
    for (x) |_, i| indices[i] = i;

    const T = @TypeOf(x[0]);
    var context = struct {
        items: []const T,
        fn greaterThan(ctx: @This(), a: usize, b: usize) bool {
            return ctx.items[a] > ctx.items[b];
        }
    }{ .items = x };

    std.sort.sort(usize, indices, context, context.greaterThan);
    return indices;
}
pub fn asc(allocator: Allocator, x: anytype) ![]@TypeOf(x[0]) {
    const T = @TypeOf(x[0]);
    var result = try allocator.dupe(T, x);
    std.sort.sort(T, result, {}, std.sort.asc(T));
    return result;
}
pub fn desc(allocator: Allocator, x: anytype) ![]@TypeOf(x[0]) {
    const T = @TypeOf(x[0]);
    var result = try allocator.dupe(T, x);
    std.sort.sort(T, result, {}, std.sort.desc(T));
    return result;
}
pub fn msum(allocator: Allocator, window: usize, x: anytype) ![]@TypeOf(x[0]) {
    if (x.len == 0 or window == 0) return &.{};
    const T = @TypeOf(x[0]);
    var result = try allocator.alloc(T, x.len);
    for (x) |_, i| {
        var start = if (i < window) 0 else i - window + 1;
        var window_sum: T = 0;
        for (x[start..i + 1]) |window_val| {
            window_sum += (window_val orelse 0);
        }
        result[i] = window_sum;
    }
    return result;
}
pub fn mcount(allocator: Allocator, window: usize, x: anytype) ![]usize {
    if (x.len == 0 or window == 0) return &.{};
    var result = try allocator.alloc(usize, x.len);
    for (x) |_, i| {
        var start = if (i < window) 0 else i - window + 1;
        var count_val: usize = 0;
        for (x[start..i + 1]) |val| {
            if (val != null) count_val += 1;
        }
        result[i] = count_val;
    }
    return result;
}
pub fn mavg(allocator: Allocator, window: usize, x: anytype) ![]f64 {
    if (x.len == 0 or window == 0) return &.{};
    const sums_ = try msum(allocator, window, x);
    const counts = try mcount(allocator, window, x);
    var result = try allocator.alloc(f64, x.len);
    for (sums_) |sum_val, i| {
        result[i] = if (counts[i] == 0) 0 else @as(f64, @floatFromInt(sum_val)) / @as(f64, @floatFromInt(counts[i]));
    }
    return result;
}
pub fn mdev(allocator: Allocator, window: usize, x: anytype) ![]f64 {
    if (x.len == 0 or window == 0) return &.{};
    const T = @TypeOf(x[0]);
    const avgs_ = try mavg(allocator, window, x);
    var result = try allocator.alloc(f64, x.len);
    var valid = std.ArrayList(T).init(allocator);
    defer valid.deinit();

    for (x) |_, i| {
        valid.clearRetainingCapacity();
        var start = if (i < window) 0 else i - window + 1;
        for (x[start..i + 1]) |window_val| {
            if (window_val != null) try valid.append(window_val.?);
        }
        if (valid.items.len == 0) {
            result[i] = 0;
        } else {
            var variance: f64 = 0;
            for (valid.items) |v| {
                variance += math.pow(f64, @as(f64, @floatFromInt(v)) - avgs_[i], 2);
            }
            variance /= @as(f64, @floatFromInt(valid.items.len));
            result[i] = math.sqrt(variance);
        }
    }
    return result;
}
pub fn xrank(allocator: Allocator, window: usize, x: anytype) ![]usize {
    if (x.len == 0 or window == 0) return &.{};
    const sorted_indices = try rank(allocator, x);
    var result = try allocator.alloc(usize, x.len);
    for (sorted_indices) |idx, i| {
        result[idx] = @divTrunc(i * window, x.len);
    }
    return result;
}

fn min_slice(comptime T: type, slice: []T) ?T {
    if (slice.len == 0) return null;
    var min_val = slice[0];
    for(slice[1..]) |val| {
        if (val < min_val) min_val = val;
    }
    return min_val;
}

fn max_slice(comptime T: type, slice: []T) ?T {
    if (slice.len == 0) return null;
    var max_val = slice[0];
    for(slice[1..]) |val| {
        if (val > max_val) max_val = val;
    }
    return max_val;
}

pub fn mmin(allocator: Allocator, window: usize, x: anytype) ![]?@TypeOf(x[0]) {
    if (x.len == 0 or window == 0) return &.{};
    const T = @TypeOf(x[0]);
    var result = try allocator.alloc(?T, x.len);
    var valid = std.ArrayList(T).init(allocator);
    defer valid.deinit();

    for (x) |_, i| {
        valid.clearRetainingCapacity();
        var start = if (i < window) 0 else i - window + 1;
        for (x[start..i + 1]) |val| {
            if (val != null) try valid.append(val.?);
        }
        result[i] = min_slice(T, valid.items);
    }
    return result;
}
pub fn mmax(allocator: Allocator, window: usize, x: anytype) ![]?@TypeOf(x[0]) {
    if (x.len == 0 or window == 0) return &.{};
    const T = @TypeOf(x[0]);
    var result = try allocator.alloc(?T, x.len);
    var valid = std.ArrayList(T).init(allocator);
    defer valid.deinit();

    for (x) |_, i| {
        valid.clearRetainingCapacity();
        var start = if (i < window) 0 else i - window + 1;
        for (x[start..i + 1]) |val| {
            if (val != null) try valid.append(val.?);
        }
        result[i] = max_slice(T, valid.items);
    }
    return result;
}
pub fn xprev(allocator: Allocator, window: usize, x: anytype) ![]?@TypeOf(x[0]) {
    if (x.len == 0 or window == 0) return &.{};
    const T = @TypeOf(x[0]);
    var result = try allocator.alloc(?T, x.len);
    for (x) |_, i| {
        var idx: isize = @as(isize, @intCast(i)) - @as(isize, @intCast(window));
        result[i] = if (idx >= 0) x[@as(usize, @intCast(idx))] else null;
    }
    return result;
}
pub fn rotate(allocator: Allocator, n: usize, x: anytype) ![]@TypeOf(x[0]) {
    if (x.len == 0) return x;
    const T = @TypeOf(x[0]);
    const n_mod = n % x.len;
    var result = try allocator.alloc(T, x.len);
    for (x) |val, i| {
        result[i] = x[(i + n_mod) % x.len];
    }
    return result;
}
pub fn ema(allocator: Allocator, alpha: f64, x: anytype) ![]@TypeOf(x[0]) {
    if (x.len == 0) return &.{};
    const T = @TypeOf(x[0]);
    var result = try allocator.alloc(T, x.len);
    var prev: T = x[0] orelse 0;
    for (x) |val, i| {
        const v: T = val orelse 0;
        const v_f = @as(f64, @floatFromInt(v));
        const p_f = @as(f64, @floatFromInt(prev));
        result[i] = @as(T, @intFromFloat(alpha * v_f + (1 - alpha) * p_f));
        prev = result[i];
    }
    return result;
}
pub fn distinct(allocator: Allocator, x: anytype) ![]@TypeOf(x[0]) {
    const T = @TypeOf(x[0]);
    var seen = std.AutoHashMap(T, void).init(allocator);
    defer seen.deinit();
    var result = std.ArrayList(T).init(allocator);
    for (x) |item| {
        if (!seen.contains(item)) {
            try seen.put(item, {});
            try result.append(item);
        }
    }
    return result.toOwnedSlice();
}
pub fn group(allocator: Allocator, x: anytype) !std.AutoHashMap(@TypeOf(x[0]), std.ArrayListUnmanaged(usize)) {
    const T = @TypeOf(x[0]);
    var groups = std.AutoHashMap(T, std.ArrayListUnmanaged(usize)).init(allocator);
    for (x) |val, i| {
        var gop = try groups.getOrPut(val);
        if (!gop.found) {
            gop.value.* = .{};
        }
        try gop.value.append(allocator, i);
    }
    return groups;
}
pub fn where(allocator: Allocator, x: []const bool) ![]usize {
    var result = std.ArrayList(usize).init(allocator);
    for (x) |val, i| {
        if (val) try result.append(i);
    }
